#include <atomic>
#include <array>
#include <cstddef>
#include <optional>
#include <new>

template<typename T, size_t Capacity>
class LockFreeSPSCQueue {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of two");
    std::array<T, Capacity> buffer_{};
    alignas(64) std::atomic<size_t> write_idx_{0};
    alignas(64) std::atomic<size_t> read_idx_{0};
public:
    bool push(const T& item) {
        size_t current_write = write_idx_.load(std::memory_order_relaxed);
        size_t current_read = read_idx_.load(std::memory_order_acquire);
        if (current_write - current_read >= Capacity) return false;
        buffer_[current_write & (Capacity - 1)] = item;
        write_idx_.store(current_write + 1, std::memory_order_release);
        return true;
    }
    std::optional<T> pop() {
        size_t current_read = read_idx_.load(std::memory_order_relaxed);
        size_t current_write = write_idx_.load(std::memory_order_acquire);
        if (current_read == current_write) return std::nullopt;
        T value = buffer_[current_read & (Capacity - 1)];
        read_idx_.store(current_read + 1, std::memory_order_release);
        return value;
    }
    bool empty() const noexcept {
        return read_idx_.load(std::memory_order_relaxed) == write_idx_.load(std::memory_order_relaxed);
    }
    size_t size() const noexcept {
        return write_idx_.load(std::memory_order_relaxed) - read_idx_.load(std::memory_order_relaxed);
    }
};

