#include <cassert>
int main() {
    LockFreeSPSCQueue<int, 4> q;
    assert(q.empty());
    assert(q.push(10));
    assert(q.push(20));
    assert(q.size() == 2);
    assert(q.pop().value() == 10);
    assert(q.pop().value() == 20);
    assert(q.empty());
    return 0;
}
